from pathlib import Path

def apply_nascita(root):
 d=Path(root)/'dist';s=(d/'documenti.html').read_text();start=s.index('<main id="contenuto">');end=s.index('</main>',start)+7
 body='''<main id="contenuto"><div class="page-heading"><p class="eyebrow">DOCUMENTI DELL’ARCHIVIO</p><h1>Giovanni Martinelli · Atto di nascita</h1><p>Monopoli, 1882 · Atto n. 405</p><p><a href="documenti.html">← Torna ai Documenti</a></p></div><article class="page-content"><h2>Due date, due momenti distinti</h2><p><strong>Nascita: 23 giugno 1882, ore 16, a Monopoli.</strong><br>Dichiarazione e redazione dell’atto: 25 giugno 1882.</p><p>L’intestazione reca «addì Venticinque di Giugno». Nel corpo dell’atto il dichiarante riferisce la nascita alle ore «pomeridiane quattro» del «Ventitré del corrente mese». Il 25 giugno è quindi la data della registrazione, distinta dalla nascita.</p><p>Padre: Sante Martinelli. Madre: Marianna Antonelli. Questi dati sono letti dalla riproduzione manoscritta fornita dalla famiglia.</p><h2>Il documento</h2><p>Tocca l’immagine per aprirla e ingrandirla. Lo screenshot è conservato senza modifiche; la risoluzione disponibile è quella fornita dalla famiglia.</p><figure><a href="assets/atto-nascita-giovanni/atto-405.png" target="_blank" rel="noopener"><img src="assets/atto-nascita-giovanni/atto-405.png" alt="Atto numero 405: nascita di Giovanni Martinelli, 23 giugno 1882, dichiarata il 25 giugno" style="width:100%;height:auto;max-height:none;object-fit:contain"></a><figcaption>Particolare dell’atto n. 405.</figcaption></figure><p><a href="assets/atto-nascita-giovanni/atto-405.png" download>Scarica l’immagine dell’atto</a></p><h2>Fonte archivistica</h2><p>Archivio di Stato di Bari → Stato civile italiano → Monopoli → 1882 → Nati. Pagina digitale 150 di 283, come indicato nella schermata del Portale Antenati fornita dalla famiglia il 15 novembre 2026.</p><p><a href="https://antenati.cultura.gov.it/ark:/12657/an_ua4280974" target="_blank" rel="noopener">Consulta il registro sul Portale Antenati</a></p><details><summary>Visualizza la schermata con i riferimenti archivistici</summary><a href="assets/atto-nascita-giovanni/registro-pagina-150.png" target="_blank" rel="noopener"><img src="assets/atto-nascita-giovanni/registro-pagina-150.png" alt="Portale Antenati: registro Nati Monopoli 1882, pagina 150" loading="lazy" style="width:100%;height:auto;max-height:none"></a></details><p>La genealogia consultabile è aggiornata con questa fonte. Le scansioni e i PDF storici dell’archivio rimangono documenti originali e non vengono riscritti.</p></article></main>'''
 s=s[:start]+body+s[end:];s=s.replace('<title>Documenti · Famiglia Martinelli</title>','<title>Atto di nascita di Giovanni Martinelli · Famiglia Martinelli</title>');(d/'atto-nascita-giovanni.html').write_text(s)
